ALTER TABLE tasks ADD COLUMN IF NOT EXISTS archived BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE tasks ADD COLUMN IF NOT EXISTS tags VARCHAR(2000) NOT NULL DEFAULT '';
ALTER TABLE tasks ADD COLUMN IF NOT EXISTS recurrence VARCHAR(16) NOT NULL DEFAULT 'NONE';
ALTER TABLE tasks ADD COLUMN IF NOT EXISTS recurrence_day INTEGER;
ALTER TABLE tasks ADD COLUMN IF NOT EXISTS series_id UUID;
ALTER TABLE tasks ADD COLUMN IF NOT EXISTS successor_id UUID;
ALTER TABLE tasks ADD COLUMN IF NOT EXISTS version BIGINT NOT NULL DEFAULT 0;
ALTER TABLE habits ADD COLUMN IF NOT EXISTS archived BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE courses ADD COLUMN IF NOT EXISTS archived BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE career_applications ADD COLUMN IF NOT EXISTS archived BOOLEAN NOT NULL DEFAULT FALSE;
CREATE TABLE IF NOT EXISTS local_preferences (id INTEGER PRIMARY KEY CHECK (id=1), display_name VARCHAR(80) NOT NULL, timezone VARCHAR(80) NOT NULL, week_start INTEGER NOT NULL, initialized BOOLEAN NOT NULL DEFAULT FALSE, reminders_enabled BOOLEAN NOT NULL DEFAULT TRUE);
INSERT INTO local_preferences VALUES (1, 'Your workspace', 'Asia/Kolkata', 0, FALSE, TRUE);
CREATE TABLE IF NOT EXISTS local_notes (id UUID PRIMARY KEY, domain VARCHAR(32) NOT NULL, title VARCHAR(255) NOT NULL, content CLOB NOT NULL, plain_text CLOB NOT NULL, tags VARCHAR(2000) NOT NULL, pinned BOOLEAN NOT NULL DEFAULT FALSE, archived BOOLEAN NOT NULL DEFAULT FALSE, revision BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE IF NOT EXISTS calendar_events (id UUID PRIMARY KEY, domain VARCHAR(32) NOT NULL, title VARCHAR(255) NOT NULL, description VARCHAR(4000) NOT NULL, all_day BOOLEAN NOT NULL, start_at TIMESTAMP WITH TIME ZONE, end_at TIMESTAMP WITH TIME ZONE, start_date DATE, end_date DATE, remind_at TIMESTAMP WITH TIME ZONE, archived BOOLEAN NOT NULL DEFAULT FALSE, revision BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE INDEX idx_local_notes_domain ON local_notes(domain, archived);
CREATE INDEX idx_calendar_events_domain ON calendar_events(domain, archived);
CREATE TABLE IF NOT EXISTS desktop_reminder_deliveries (task_id UUID NOT NULL, remind_at TIMESTAMP WITH TIME ZONE NOT NULL, delivered_at TIMESTAMP WITH TIME ZONE NOT NULL, PRIMARY KEY(task_id, remind_at));
CREATE TABLE IF NOT EXISTS desktop_reminder_attempts (record_id UUID NOT NULL, kind VARCHAR(16) NOT NULL, remind_at TIMESTAMP WITH TIME ZONE NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, lease_until TIMESTAMP WITH TIME ZONE, delivered_at TIMESTAMP WITH TIME ZONE, last_error VARCHAR(300), PRIMARY KEY(record_id,kind,remind_at));
INSERT INTO desktop_reminder_attempts(record_id,kind,remind_at,attempts,delivered_at) SELECT task_id,'task',remind_at,1,delivered_at FROM desktop_reminder_deliveries;
